            """)
        @OptionGroup var g: GlobalOptions
        @Argument(help: ArgumentHelp("<과목>/<묶음>", valueName: "set"), completion: Complete.ref("ProblemSet")) var set: String
        @Argument(help: "문제 번호") var number: String
        @Argument(help: ArgumentHelp("같은 과목의 단원", valueName: "unit"), completion: Complete.ref("Unit")) var unit: String = ""
        @Flag(name: .customLong("off"), help: "연결 떼기") var off = false

        func run() throws {
            let ctx = try CLI.context(g)
            let r = Resolver(ctx)
            let (c, setName) = try r.split(set)
            let action = FolioActions.ProblemLinkUnit(
                course: c.id,
                set: try r.id("ProblemSet", setName, in: c),
                number: number,
                unit: try r.id("Unit", unit, in: c),
                linked: !off
            )
            try perform(spec: action, g, ctx: ctx)
        }
    }

    struct ReviewRecord: ParsableCommand {
        static let configuration = CommandConfiguration(commandName: "record", abstract: "단원 복습 결과와 걸린 시간을 기록", discussion: """
            예시:
              folio review record EC4207/매칭 good --start \"2026-10-28 20:00\" --end \"2026-10-28 20:40\"
            """)
        @OptionGroup var g: GlobalOptions
        @Argument(help: ArgumentHelp("<과목>/<단원>", valueName: "unit"), completion: Complete.ref("Unit")) var unit: String
        @Argument(help: "결과") var result: ReviewResult
        @Option(help: ArgumentHelp("시작 시각", valueName: "date")) var start: DateArg
        @Option(help: ArgumentHelp("끝난 시각", valueName: "date")) var end: DateArg

        func run() throws {
            let ctx = try CLI.context(g)
            let r = Resolver(ctx)
            let (c, unitName) = try r.split(unit)
            let action = FolioActions.ReviewRecord(
                course: c.id,
                unit: try r.id("Unit", unitName, in: c),
                result: result,
                start: start.date,
                end: end.date
            )
            try perform(spec: action, g, ctx: ctx)
        }
    }
}
